    for keyword, count in data['search_results_per_keyword'].items():
        report += f"  • {keyword}: {count} 条\n"
else:
    # 从 feeds 中统计
    keyword_counts = {}
    for feed in data.get('feeds', []):
        keyword = feed.get('keyword', '未知')
